import SwiftUI
public struct ReportBlockView:View{@State var reason=0;public init(){};public var body:some View{Form{Picker("理由",selection:$reason){Text("迷惑行為・嫌がらせ").tag(0);Text("不適切な発言・行為").tag(1);Text("外部サービスへの誘導").tag(2);Text("その他").tag(3)};Button("通報する"){}.foregroundStyle(.red);Button("この芸人をブロック"){}.foregroundStyle(.red)}.navigationTitle("通報・ブロック")}}
public struct ConnectionErrorView:View{public init(){};public var body:some View{VStack(spacing:22){Spacer();Image(systemName:"exclamationmark.circle").font(.system(size:70)).foregroundStyle(WaiwaiTheme.yellow);Text("通話に接続できません").font(.title2.bold()).foregroundStyle(.white);Text("通信環境を確認してもう一度お試しください").foregroundStyle(.white.opacity(0.7));Button("再接続する"){}.buttonStyle(WaiwaiPrimaryButtonStyle());Spacer()}.padding(20).background(WaiwaiTheme.ink.ignoresSafeArea())}}
public struct EmptyStateView:View{public let title:String;public let action:String;public init(title:String,action:String){self.title=title;self.action=action};public var body:some View{VStack(spacing:18){Spacer();Image(systemName:"sparkles").font(.largeTitle);Text(title).font(.headline);Button(action){}.buttonStyle(WaiwaiPrimaryButtonStyle());Spacer()}.padding(20)}}
public struct ComedianIncomingCallView:View{public init(){};public var body:some View{VStack(spacing:24){Spacer();Circle().fill(.white.opacity(0.12)).frame(width:160,height:160);Text("こんぺ").font(.title.bold());Text("音声通話・10分").foregroundStyle(.white.opacity(0.7));HStack{Button("拒否"){}.frame(maxWidth:.infinity,minHeight:54).background(.red).clipShape(Capsule());Button("応答"){}.frame(maxWidth:.infinity,minHeight:54).background(WaiwaiTheme.online).clipShape(Capsule())};Spacer()}.padding(20).foregroundStyle(.white).background(WaiwaiTheme.ink.ignoresSafeArea())}}
